1	package com.example.starter.service;
2	
3	import java.time.Instant;
4	import java.time.LocalDate;
5	import java.time.ZoneOffset;
6	import java.time.temporal.ChronoUnit;
7	import java.util.ArrayList;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.concurrent.ThreadLocalRandom;
12	import java.util.stream.Collectors;
13	
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	
17	import com.example.starter.domain.AlertEvent;
18	import com.example.starter.domain.AlertType;
19	import com.example.starter.domain.Allocation;
20	import com.example.starter.domain.CurtailOrder;
21	import com.example.starter.domain.DispatchCycle;
22	import com.example.starter.domain.ExecutionReport;
23	import com.example.starter.domain.IdempotentRecord;
24	import com.example.starter.domain.LateReportEvent;
25	import com.example.starter.domain.OrderStatus;
26	import com.example.starter.domain.PlanSegment;
27	import com.example.starter.domain.PlanVersion;
28	import com.example.starter.domain.Turbine;
29	import com.example.starter.dto.AllocationItem;
30	import com.example.starter.dto.AlertView;
31	import com.example.starter.dto.OrderBasisResponse;
32	import com.example.starter.dto.OrderDetailResponse;
33	import com.example.starter.dto.OrderReceiveRequest;
34	import com.example.starter.dto.OrderReceiveResponse;
35	import com.example.starter.dto.PlanOrderReceiveRequest;
36	import com.example.starter.dto.PlanOrderReceiveResponse;
37	import com.example.starter.dto.ReportRequest;
38	import com.example.starter.dto.ReportResponse;
39	import com.example.starter.dto.SettleResponse;
40	import com.example.starter.repo.DispatchRepository;
41	import com.example.starter.repo.IdempotentRepository;
42	import com.example.starter.repo.PlanRepository;
43	import com.example.starter.repo.TurbineRepository;
44	import com.example.starter.support.Canonical;
45	import com.example.starter.support.Fingerprints;
46	import com.example.starter.support.ServiceClock;
47	import com.example.starter.web.ApiBadRequestException;
48	import com.example.starter.web.ApiConflictException;
49	import com.example.starter.web.ApiNotFoundException;
50	import com.example.starter.web.ApiUnprocessableException;
51	import com.fasterxml.jackson.core.JsonProcessingException;
52	import com.fasterxml.jackson.databind.ObjectMapper;
53	
54	/**
55	 * 限电指令流转服务：接收分摊、新旧指令原子切换、执行回报去重、
56	 * 下发满 10 分钟未达标告警并按最新可用出力重分摊、日结封存。
57	 */
58	@Service
59	public class DispatchService {
60	
61	    /** 下发后达标判定时长：恰满 10 分钟即触发判定。 */
62	    static final long DUE_MINUTES = 10;
63	
64	    private final ServiceClock clock;
65	    private final TurbineRepository turbineRepository;
66	    private final DispatchRepository dispatchRepository;
67	    private final IdempotentRepository idempotentRepository;
68	    private final PlanRepository planRepository;
69	    private final ObjectMapper objectMapper;
70	
71	    public DispatchService(ServiceClock clock,
72	                           TurbineRepository turbineRepository,
73	                           DispatchRepository dispatchRepository,
74	                           IdempotentRepository idempotentRepository,
75	                           PlanRepository planRepository,
76	                           ObjectMapper objectMapper) {
77	        this.clock = clock;
78	        this.turbineRepository = turbineRepository;
79	        this.dispatchRepository = dispatchRepository;
80	        this.idempotentRepository = idempotentRepository;
81	        this.planRepository = planRepository;
82	        this.objectMapper = objectMapper;
83	    }
84	
85	    /**
86	     * 接收限电指令：加风场行锁串行化同风场并发接收；新指令生效与旧指令作废在同一事务完成。
87	     */
88	    @Transactional
89	    public OrderReceiveResponse receive(OrderReceiveRequest request) {
90	        Instant now = clock.now();
91	        String fingerprint = Fingerprints.sha256(
92	                "ORDER|" + request.requestId() + "|" + request.farmCode() + "|" + request.targetPowerKw());
93	
94	        // 行锁前先处理确定的重放/冲突；未命中的并发情况在锁后二次确认。
95	        IdempotentRecord existing = idempotentRepository.findByRequestId(request.requestId());
96	        if (existing != null) {
97	            return resolveOrderIdempotent(existing, fingerprint);
98	        }
99	
100	        if (!turbineRepository.lockFarmRow(request.farmCode())) {
101	            throw new ApiBadRequestException("风场不存在：" + request.farmCode());
102	        }
103	
104	        existing = idempotentRepository.findByRequestId(request.requestId());
105	        if (existing != null) {
106	            return resolveOrderIdempotent(existing, fingerprint);
107	        }
108	
109	        List<Turbine> turbines = turbineRepository.findByFarm(request.farmCode());
110	        int farmAvailable = turbines.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
111	
112	        CurtailOrder active = dispatchRepository.findActiveOrder(request.farmCode());
113	
114	        // 同一风场同一接收时刻只允许一个执行中指令：与执行中指令同时刻到达的并发接收冲突 409，
115	        // 保证并发接收唯一受理；早于当前时刻存在的旧指令视为先后到达，由新指令原子切换。
116	        if (active != null && !active.getReceivedAt().isBefore(now)) {
117	            throw new ApiConflictException(
118	                    "风场同一时刻已有执行中限电指令：" + active.getOrderNo());
119	        }
120	
121	        // 先落幂等占位（唯一约束兜底并发受理），再做业务写入。
122	        IdempotentRecord record = new IdempotentRecord();
123	        record.setRequestId(request.requestId());
124	        record.setBizType("ORDER");
125	        record.setFingerprint(fingerprint);
126	        record.setCreatedAt(now);
127	        record.setResponseBody("");
128	        if (!idempotentRepository.tryInsert(record)) {
129	            IdempotentRecord winner = idempotentRepository.findByRequestId(request.requestId());
130	            return resolveOrderIdempotent(winner, fingerprint);
131	        }
132	
133	        List<Allocation> allocations =
134	                AllocationEngine.allocate(turbines, request.targetPowerKw(), 0L, 1);
135	
136	        CurtailOrder order = new CurtailOrder();
137	        order.setOrderNo(generateOrderNo(now));
138	        order.setFarmCode(request.farmCode());
139	        order.setRequestId(request.requestId());
140	        order.setFingerprint(fingerprint);
141	        order.setTargetPowerKw(request.targetPowerKw());
142	        order.setStatus(OrderStatus.DISPATCHED);
143	        order.setCurrentCycleNo(1);
144	        order.setReceivedAt(now);
145	        // 先以非执行中插入拿 id，旧指令作废后再置执行中，避免唯一索引出现双 Y。
146	        long newId = dispatchRepository.insertOrder(order);
147	        allocations.forEach(a -> a.setOrderId(newId));
148	
149	        if (active != null) {
150	            // 同一事务：旧指令作废（active 释放）→ 新指令生效，不存在双指令同时生效窗口。
151	            dispatchRepository.markSuperseded(active.getId(), newId);
152	        }
153	        dispatchRepository.insertCycle(buildCycle(newId, 1, now));
154	        dispatchRepository.insertAllocations(newId, 1, allocations);
155	        // 旧指令已在本事务作废（active 释放），此处将新指令置为执行中。
156	        dispatchRepository.activateOrder(newId);
157	
158	        OrderReceiveResponse response = buildReceiveResponse(
159	                order, turbines, allocations, farmAvailable, false);
160	        idempotentRepository.updateRefAndResponse(request.requestId(), newId, toJson(response));
161	        return response;
162	    }
163	
164	    /**
165	     * 计划绑定模式接收限电指令：
166	     * 在风场行锁 + 计划版本行锁内校验并冻结版本与该段核定基数；过期（非当前）版本拒绝绑定（422）；
167	     * 可参与出力 = min(各机组实时可用, 该段核定计划)，据此套用最低保留与比例分摊，目标不可实现整单拒绝（422）；
168	     * 冻结后新计划发布不重算已受理指令；同 requestId 同参重放首次冻结结果，异参 409，失败不占键。
169	     */
170	    @Transactional
171	    public PlanOrderReceiveResponse receivePlanOrder(PlanOrderReceiveRequest request) {
172	        Instant now = clock.now();
173	        // 指纹覆盖调用方给出的精确受理时刻（业务参数一部分）；指令落库受理时刻取服务端时钟。
174	        String fingerprint = fingerprintPlanOrder(request, request.operateAt());
175	
176	        IdempotentRecord existing = idempotentRepository.findByRequestId(request.requestId());
177	        if (existing != null) {
178	            return resolvePlanOrderIdempotent(existing, fingerprint);
179	        }
180	
181	        if (!turbineRepository.lockFarmRow(request.farmCode())) {
182	            throw new ApiBadRequestException("风场不存在：" + request.farmCode());
183	        }
184	
185	        existing = idempotentRepository.findByRequestId(request.requestId());
186	        if (existing != null) {
187	            return resolvePlanOrderIdempotent(existing, fingerprint);
188	        }
189	
190	        CurtailOrder active = dispatchRepository.findActiveOrder(request.farmCode());
191	        if (active != null && !active.getReceivedAt().isBefore(now)) {
192	            throw new ApiConflictException(
193	                    "风场同一时刻已有执行中限电指令：" + active.getOrderNo());
194	        }
195	
196	        // 锁定指定版本行：与计划发布竞争时，要么在发布替换指针前读到它（此时它仍是当前版本），
197	        // 要么等发布提交后读到最新值；校验的版本与后续读取的段基数始终来自同一锁定快照。
198	        PlanVersion version = planRepository.lockVersion(
199	                request.farmCode(), request.planDate(), request.planVersionNo());
200	        if (version == null) {
201	            throw new ApiNotFoundException(
202	                    "计划版本不存在：" + request.farmCode() + " " + request.planDate()
203	                            + " v" + request.planVersionNo());
204	        }
205	        if (!"Y".equals(version.getCurrentFlag())) {
206	            throw new ApiUnprocessableException(
207	                    "计划版本 v" + request.planVersionNo() + " 已过期，新指令只能绑定当前版本");
208	        }
209	
210	        List<Turbine> turbines = turbineRepository.findByFarm(request.farmCode());
211	        List<PlanSegment> segments =
212	                planRepository.findSegments(version.getId(), request.segmentIndex());
213	        Map<Long, Integer> plannedById = segments.stream()
214	                .collect(Collectors.toMap(PlanSegment::getTurbineId, PlanSegment::getPowerKw));
215	        if (segments.size() != turbines.size()
216	                || !plannedById.keySet().equals(
217	                        turbines.stream().map(Turbine::getId).collect(Collectors.toSet()))) {
218	            // 不可达：发布已整版校验；保留防御。
219	            throw new ApiUnprocessableException(
220	                    "计划第 " + request.segmentIndex() + " 段机组基数不完整，无法受理");
221	        }
222	
223	        List<Turbine> participating = applyPlanBasis(turbines, plannedById);
224	        int farmParticipating = participating.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
225	
226	        IdempotentRecord record = new IdempotentRecord();
227	        record.setRequestId(request.requestId());
228	        record.setBizType("PLAN_ORDER");
229	        record.setFingerprint(fingerprint);
230	        record.setCreatedAt(now);
231	        record.setResponseBody("");
232	        if (!idempotentRepository.tryInsert(record)) {
233	            return resolvePlanOrderIdempotent(
234	                    idempotentRepository.findByRequestId(request.requestId()), fingerprint);
235	        }
236	
237	        // 目标不可实现（高于可参与出力，或低于按可参与出力计的可实现下限）：整单拒绝（422），
238	        // 事务回滚——上面的幂等占位随之回滚，失败不占键。旧未绑定模式仍维持 400 语义不变。
239	        List<Allocation> allocations;
240	        try {
241	            allocations = AllocationEngine.allocate(
242	                    participating, request.targetPowerKw(), 0L, 1);
243	        } catch (ApiBadRequestException ex) {
244	            throw new ApiUnprocessableException(ex.getMessage());
245	        }
246	        freezePlanBasis(allocations, turbines, plannedById);
247	
248	        CurtailOrder order = new CurtailOrder();
249	        order.setOrderNo(generateOrderNo(now));
250	        order.setFarmCode(request.farmCode());
251	        order.setRequestId(request.requestId());
252	        order.setFingerprint(fingerprint);
253	        order.setTargetPowerKw(request.targetPowerKw());
254	        order.setStatus(OrderStatus.DISPATCHED);
255	        order.setCurrentCycleNo(1);
256	        order.setReceivedAt(now);
257	        order.setPlanVersionId(version.getId());
258	        order.setPlanVersionNo(version.getVersionNo());
259	        order.setPlanDate(request.planDate());
260	        order.setSegmentIndex(request.segmentIndex());
261	        long newId = dispatchRepository.insertOrder(order);
262	        allocations.forEach(a -> a.setOrderId(newId));
263	
264	        if (active != null) {
265	            dispatchRepository.markSuperseded(active.getId(), newId);
266	        }
267	        dispatchRepository.insertCycle(buildCycle(newId, 1, now));
268	        dispatchRepository.insertAllocations(newId, 1, allocations);
269	        dispatchRepository.activateOrder(newId);
270	
271	        Map<Long, Turbine> byId = new LinkedHashMap<>();
272	        turbines.forEach(t -> byId.put(t.getId(), t));
273	        List<AllocationItem> items = allocations.stream()
274	                .map(a -> toItem(a, byId.get(a.getTurbineId())))
275	                .toList();
276	        boolean noCurtailment = farmParticipating == request.targetPowerKw();
277	        PlanOrderReceiveResponse response = new PlanOrderReceiveResponse(newId, order.getOrderNo(),
278	                request.requestId(), request.farmCode(), request.targetPowerKw(),
279	                farmParticipating, farmParticipating - request.targetPowerKw(),
280	                OrderStatus.DISPATCHED.name(), 1, noCurtailment,
281	                version.getId(), version.getVersionNo(), request.planDate(),
282	                request.segmentIndex(), true, items, false);
283	        idempotentRepository.updateRefAndResponse(request.requestId(), newId, toJson(response));
284	        return response;
285	    }
286	
287	    private PlanOrderReceiveResponse resolvePlanOrderIdempotent(
288	            IdempotentRecord existing, String fingerprint) {
289	        if (!existing.getFingerprint().equals(fingerprint)) {
290	            throw new ApiConflictException("相同 requestId 的业务参数与首次请求不一致");
291	        }
292	        if (existing.getResponseBody() != null && !existing.getResponseBody().isBlank()) {
293	            return fromJson(existing.getResponseBody(), PlanOrderReceiveResponse.class).asReplay();
294	        }
295	        throw new ApiConflictException("首次请求仍在处理中");
296	    }
297	
298	    /**
299	     * 指令基数证据：返回绑定版本、UTC 时段及各轮每机组“核定计划/实时可用/参与出力/分摊”冻结值。
300	     * 未绑定计划的指令无此证据（404）；指令本身不存在亦 404。
301	     */
302	    @Transactional(readOnly = true)
303	    public OrderBasisResponse basis(String orderNo) {
304	        CurtailOrder order = dispatchRepository.findOrderByNo(orderNo);
305	        if (order == null) {
306	            throw new ApiNotFoundException("指令不存在：" + orderNo);
307	        }
308	        if (order.getPlanVersionId() == null) {
309	            throw new ApiNotFoundException("指令未绑定日前计划，无计划基数证据：" + orderNo);
310	        }
311	        PlanVersion version = planRepository.findVersionById(order.getPlanVersionId());
312	        List<Turbine> turbines = turbineRepository.findByFarm(order.getFarmCode());
313	        Map<Long, Turbine> turbineById = turbines.stream()
314	                .collect(Collectors.toMap(Turbine::getId, t -> t));
315	
316	        Instant segmentStart = order.getPlanDate().atStartOfDay()
317	                .plusMinutes(15L * order.getSegmentIndex()).toInstant(ZoneOffset.UTC);
318	        List<DispatchCycle> cycles = dispatchRepository.findCycles(order.getId());
319	        List<Allocation> all = dispatchRepository.findAllAllocations(order.getId());
320	        List<OrderBasisResponse.CycleBasisView> cycleViews = new ArrayList<>();
321	        for (DispatchCycle c : cycles) {
322	            List<OrderBasisResponse.TurbineBasisItem> items = all.stream()
323	                    .filter(a -> a.getCycleNo() == c.getCycleNo())
324	                    .map(a -> {
325	                        Turbine t = turbineById.get(a.getTurbineId());
326	                        int planned = a.getPlannedPowerKw();
327	                        int realtime = a.getRealtimeAvailableKw();
328	                        return new OrderBasisResponse.TurbineBasisItem(
329	                                t.getTurbineCode(), planned, realtime,
330	                                Math.min(planned, realtime), t.getTechnicalMinKw(),
331	                                a.getTargetPowerKw(), a.getCurtailKw());
332	                    })
333	                    .toList();
334	            cycleViews.add(new OrderBasisResponse.CycleBasisView(
335	                    c.getCycleNo(), c.getDispatchedAt(), items));
336	        }
337	
338	        return new OrderBasisResponse(order.getId(), order.getOrderNo(), order.getFarmCode(),
339	                order.getPlanVersionId(), order.getPlanVersionNo(), order.getPlanDate(),
340	                order.getSegmentIndex(), segmentStart, segmentStart.plusSeconds(15 * 60L),
341	                version != null && "Y".equals(version.getCurrentFlag()), cycleViews);
342	    }
343	
344	    /** 计划绑定指令指纹：结构化 TLV，覆盖全部业务参数与精确受理时刻。 */
345	    private String fingerprintPlanOrder(PlanOrderReceiveRequest request, Instant receivedAt) {
346	        String canonical = Canonical.obj(
347	                "bizType", Canonical.str("PLAN_ORDER"),
348	                "requestId", Canonical.str(request.requestId()),
349	                "farmCode", Canonical.str(request.farmCode()),
350	                "targetPowerKw", Canonical.integer(request.targetPowerKw()),
351	                "planDate", Canonical.date(request.planDate()),
352	                "segmentIndex", Canonical.integer(request.segmentIndex()),
353	                "planVersionNo", Canonical.integer(request.planVersionNo()),
354	                "receivedAt", Canonical.instant(receivedAt));
355	        return Canonical.sha256(canonical);
356	    }
357	
358	    private OrderReceiveResponse resolveOrderIdempotent(IdempotentRecord existing, String fingerprint) {        if (!existing.getFingerprint().equals(fingerprint)) {
359	            throw new ApiConflictException("相同 requestId 的业务参数与首次请求不一致");
360	        }
361	        if (existing.getResponseBody() != null && !existing.getResponseBody().isBlank()) {
362	            return fromJson(existing.getResponseBody(), OrderReceiveResponse.class).asReplay();
363	        }
364	        // 占位尚未回填（理论仅极端并发），按实体重建。
365	        CurtailOrder order = dispatchRepository.findOrderById(existing.getRefId());
366	        throw new ApiConflictException("首次请求仍在处理中");
367	    }
368	
369	    /**
370	     * 机组执行回报：按机组＋时刻去重；满 10 分钟未达标则告警并按最新可用出力重分摊。
371	     */
372	    @Transactional
373	    public ReportResponse report(ReportRequest request) {
374	        Instant now = clock.now();
375	        String fingerprint = Fingerprints.sha256(
376	                "REPORT|" + request.requestId() + "|" + request.turbineCode() + "|"
377	                        + request.measuredAt() + "|" + request.powerKw());
378	
379	        IdempotentRecord existing = idempotentRepository.findByRequestId(request.requestId());
380	        if (existing != null) {
381	            return resolveReportIdempotent(existing, fingerprint);
382	        }
383	
384	        Turbine turbine = turbineRepository.findByCode(request.turbineCode());
385	        if (turbine == null) {
386	            throw new ApiNotFoundException("机组不存在：" + request.turbineCode());
387	        }
388	
389	        // 优先归属执行中指令；无执行中指令时取最新指令用于判定封存后的迟到回报。
390	        CurtailOrder order = dispatchRepository.findActiveOrder(turbine.getFarmCode());
391	        if (order == null) {
392	            order = dispatchRepository.findLatestOrder(turbine.getFarmCode());
393	        }
394	        if (order == null) {
395	            throw new ApiBadRequestException("该风场尚无任何限电指令，无法接收回报");
396	        }
397	
398	        // 封存（或作废）后迟到回报：只登记迟到事件，不进入执行曲线。
399	        if (order.getStatus() == OrderStatus.SETTLED || order.getStatus() == OrderStatus.SUPERSEDED) {
400	            return recordLateReport(order, request, now, fingerprint);
401	        }
402	
403	        // 锁定执行中指令行，串行化同指令的并发回报：保证达标判定/告警重分摊不重入。
404	        CurtailOrder locked = dispatchRepository.lockOrderById(order.getId());
405	        if (locked.getStatus() != OrderStatus.DISPATCHED) {
406	            // 持锁期间指令状态可能已被日结/切换改变：按终态迟到回报处理。
407	            return recordLateReport(locked, request, now, fingerprint);
408	        }
409	        order = locked;
410	
411	        // 按机组＋时刻去重：不同 requestId 回报同一时刻点，返回首次结果，不重复入库。
412	        ExecutionReport samePoint =
413	                dispatchRepository.findReportByTurbineAndTime(turbine.getId(), request.measuredAt());
414	        if (samePoint != null) {
415	            CurtailPointView view = loadPointView(samePoint, turbine);
416	            return new ReportResponse(samePoint.getRequestId(), view.orderNo(), turbine.getTurbineCode(),
417	                    samePoint.getMeasuredAt().toString(), samePoint.getPowerKw(), false, true);
418	        }
419	
420	        IdempotentRecord record = newIdempotent(request.requestId(), "REPORT", fingerprint, now);
421	        if (!idempotentRepository.tryInsert(record)) {
422	            return resolveReportIdempotent(
423	                    idempotentRepository.findByRequestId(request.requestId()), fingerprint);
424	        }
425	
426	        ExecutionReport report = new ExecutionReport();
427	        report.setRequestId(request.requestId());
428	        report.setOrderId(order.getId());
429	        report.setTurbineId(turbine.getId());
430	        report.setMeasuredAt(request.measuredAt());
431	        report.setPowerKw(request.powerKw());
432	        report.setReceivedAt(now);
433	        try {
434	            dispatchRepository.insertReport(report);
435	        } catch (org.springframework.dao.DuplicateKeyException ex) {
436	            // 同机组＋时刻并发回报：唯一约束兜底，回查返回首次结果（按时刻去重）。
437	            ExecutionReport winner =
438	                    dispatchRepository.findReportByTurbineAndTime(turbine.getId(), request.measuredAt());
439	            CurtailOrder owner = winner == null ? order
440	                    : dispatchRepository.findOrderById(winner.getOrderId());
441	            ReportResponse dedup = new ReportResponse(
442	                    winner == null ? request.requestId() : winner.getRequestId(),
443	                    owner.getOrderNo(), turbine.getTurbineCode(),
444	                    request.measuredAt().toString(),
445	                    winner == null ? request.powerKw() : winner.getPowerKw(),
446	                    false, true);
447	            idempotentRepository.updateRefAndResponse(
448	                    request.requestId(), winner == null ? null : winner.getId(), toJson(dedup));
449	            return dedup;
450	        }
451	
452	        // 最新可用出力以回报实测值刷新，作为重分摊依据。
453	        turbineRepository.updateAvailablePower(turbine.getId(), request.powerKw(), now);
454	        turbine.setAvailablePowerKw(request.powerKw());
455	
456	        maybeAlertAndReallocate(order, now);
457	
458	        ReportResponse response = new ReportResponse(request.requestId(), order.getOrderNo(),
459	                request.turbineCode(), request.measuredAt().toString(), request.powerKw(),
460	                false, false);
461	        idempotentRepository.updateRefAndResponse(request.requestId(), report.getId(), toJson(response));
462	        return response;
463	    }
464	
465	    private record CurtailPointView(String orderNo) {
466	    }
467	
468	    /** 登记封存/作废后的迟到回报：幂等占位 + 迟到事件，返回 late=true。 */
469	    private ReportResponse recordLateReport(CurtailOrder order, ReportRequest request,
470	                                            Instant now, String fingerprint) {
471	        IdempotentRecord record = newIdempotent(request.requestId(), "REPORT", fingerprint, now);
472	        if (!idempotentRepository.tryInsert(record)) {
473	            return resolveReportIdempotent(
474	                    idempotentRepository.findByRequestId(request.requestId()), fingerprint);
475	        }
476	        LateReportEvent event = new LateReportEvent();
477	        event.setOrderId(order.getId());
478	        event.setTurbineCode(request.turbineCode());
479	        event.setMeasuredAt(request.measuredAt());
480	        event.setPowerKw(request.powerKw());
481	        event.setRequestId(request.requestId());
482	        event.setRecordedAt(now);
483	        dispatchRepository.insertLateReport(event);
484	        ReportResponse response = new ReportResponse(request.requestId(), order.getOrderNo(),
485	                request.turbineCode(), request.measuredAt().toString(), request.powerKw(),
486	                true, false);
487	        idempotentRepository.updateRefAndResponse(request.requestId(), null, toJson(response));
488	        return response;
489	    }
490	
491	    private CurtailPointView loadPointView(ExecutionReport report, Turbine turbine) {
492	        CurtailOrder owner = dispatchRepository.findOrderById(report.getOrderId());
493	        return new CurtailPointView(owner == null ? null : owner.getOrderNo());
494	    }
495	
496	    /**
497	     * 达标判定与重分摊：当前轮次下发恰满 10 分钟，全场最新出力仍高于目标则告警，
498	     * 并按各机组最新可用出力重分摊生成下一轮。
499	     */
500	    private void maybeAlertAndReallocate(CurtailOrder order, Instant now) {
501	        int cycleNo = order.getCurrentCycleNo();
502	        DispatchCycle cycle = dispatchRepository.findCycles(order.getId()).stream()
503	                .filter(c -> c.getCycleNo() == cycleNo)
504	                .findFirst()
505	                .orElseThrow(() -> new ApiBadRequestException("当前下发轮次缺失：" + cycleNo));
506	
507	        // 恰满 10 分钟判定：now 早于 dueAt 不触发。
508	        if (now.isBefore(cycle.getDueAt())) {
509	            return;
510	        }
511	        if (dispatchRepository.findAlert(order.getId(), cycleNo) != null) {
512	            return;
513	        }
514	
515	        // 计划绑定指令：重分摊仍引用原计划，仅把各机组实时可用刷新为最新值，
516	        // 参与出力 = min(实时可用, 冻结核定计划)，核定计划与已受理结果不随后续新计划发布改变。
517	        if (order.getPlanVersionId() != null) {
518	            Map<Long, Integer> plannedById = dispatchRepository.findAllocations(order.getId(), 1)
519	                    .stream()
520	                    .collect(Collectors.toMap(Allocation::getTurbineId, Allocation::getPlannedPowerKw));
521	            List<Turbine> farmTurbines = turbineRepository.findByFarm(order.getFarmCode());
522	            List<Turbine> participating = applyPlanBasis(farmTurbines, plannedById);
523	            int farmParticipating = participating.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
524	            if (farmParticipating <= order.getTargetPowerKw()) {
525	                return;
526	            }
527	
528	            AlertEvent planAlert = new AlertEvent();
529	            planAlert.setOrderId(order.getId());
530	            planAlert.setCycleNo(cycleNo);
531	            planAlert.setType(AlertType.TARGET_NOT_REACHED);
532	            planAlert.setFiredAt(now);
533	            planAlert.setFarmActualKw(farmParticipating);
534	            dispatchRepository.insertAlert(planAlert);
535	
536	            int newCycleNo = cycleNo + 1;
537	            List<Allocation> reallocations =
538	                    AllocationEngine.allocate(participating, order.getTargetPowerKw(),
539	                            order.getId(), newCycleNo);
540	            freezePlanBasis(reallocations, farmTurbines, plannedById);
541	            dispatchRepository.insertCycle(buildCycle(order.getId(), newCycleNo, now));
542	            dispatchRepository.insertAllocations(order.getId(), newCycleNo, reallocations);
543	            dispatchRepository.updateAlertReallocated(order.getId(), cycleNo, newCycleNo);
544	            dispatchRepository.updateCurrentCycle(order.getId(), newCycleNo);
545	            order.setCurrentCycleNo(newCycleNo);
546	            return;
547	        }
548	
549	        List<Turbine> turbines = turbineRepository.findByFarm(order.getFarmCode());
550	        int farmActual = turbines.stream().mapToInt(Turbine::getAvailablePowerKw).sum();
551	        if (farmActual <= order.getTargetPowerKw()) {
552	            return;
553	        }
554	
555	        AlertEvent alert = new AlertEvent();
556	        alert.setOrderId(order.getId());
557	        alert.setCycleNo(cycleNo);
558	        alert.setType(AlertType.TARGET_NOT_REACHED);
559	        alert.setFiredAt(now);
560	        alert.setFarmActualKw(farmActual);
561	        dispatchRepository.insertAlert(alert);
562	
563	        int newCycleNo = cycleNo + 1;
564	        List<Allocation> reallocations =
565	                AllocationEngine.allocate(turbines, order.getTargetPowerKw(), order.getId(), newCycleNo);
566	        dispatchRepository.insertCycle(buildCycle(order.getId(), newCycleNo, now));
567	        dispatchRepository.insertAllocations(order.getId(), newCycleNo, reallocations);
568	        dispatchRepository.updateAlertReallocated(order.getId(), cycleNo, newCycleNo);
569	        dispatchRepository.updateCurrentCycle(order.getId(), newCycleNo);
570	        order.setCurrentCycleNo(newCycleNo);
571	    }
572	
573	    /**
574	     * 以冻结核定计划裁剪实时可用：返回同序机组视图，其 availablePowerKw=min(实时, 计划)，
575	     * 作为最低保留与比例分摊的输入基数。
576	     */
577	    private List<Turbine> applyPlanBasis(List<Turbine> turbines, Map<Long, Integer> plannedById) {
578	        List<Turbine> views = new ArrayList<>(turbines.size());
579	        for (Turbine t : turbines) {
580	            Integer planned = plannedById.get(t.getId());
581	            if (planned == null) {
582	                // 不可达：受理时整版覆盖全场机组且版本不可变。
583	                throw new ApiBadRequestException("计划基数缺少机组核定值：" + t.getTurbineCode());
584	            }
585	            Turbine v = new Turbine();
586	            v.setId(t.getId());
587	            v.setFarmCode(t.getFarmCode());
588	            v.setTurbineCode(t.getTurbineCode());
589	            v.setRatedPowerKw(t.getRatedPowerKw());
590	            v.setTechnicalMinKw(t.getTechnicalMinKw());
591	            v.setUpdatedAt(t.getUpdatedAt());
592	            v.setAvailablePowerKw(Math.min(t.getAvailablePowerKw(), planned));
593	            views.add(v);
594	        }
595	        return views;
596	    }
597	
598	    /** 将每轮分摊明细回填冻结的核定计划值与该轮实时可用值（参与出力取较小者）。 */
599	    private void freezePlanBasis(List<Allocation> allocations, List<Turbine> turbines,
600	                                 Map<Long, Integer> plannedById) {
601	        Map<Long, Integer> realtimeById = turbines.stream()
602	                .collect(Collectors.toMap(Turbine::getId, Turbine::getAvailablePowerKw));
603	        for (Allocation a : allocations) {
604	            int planned = plannedById.get(a.getTurbineId());
605	            int realtime = realtimeById.get(a.getTurbineId());
606	            a.setPlannedPowerKw(planned);
607	            a.setRealtimeAvailableKw(realtime);
608	            // 引擎已按 min(实时, 计划) 分摊；防御性校验参与出力一致。
609	            if (a.getBaseAvailableKw() != Math.min(realtime, planned)) {
610	                throw new ApiBadRequestException("计划参与出力基数不一致：turbineId=" + a.getTurbineId());
611	            }
612	        }
613	    }
614	
615	    private ReportResponse resolveReportIdempotent(IdempotentRecord existing, String fingerprint) {
616	        if (existing == null) {
617	            throw new ApiConflictException("并发请求处理中，请重试");
618	        }
619	        if (!existing.getFingerprint().equals(fingerprint)) {
620	            throw new ApiConflictException("相同 requestId 的业务参数与首次请求不一致");
621	        }
622	        if (existing.getResponseBody() != null && !existing.getResponseBody().isBlank()) {
623	            return fromJson(existing.getResponseBody(), ReportResponse.class).asReplay();
624	        }
625	        throw new ApiConflictException("首次请求仍在处理中");
626	    }
627	
628	    /**
629	     * 日结封存：终态；已封存重复封存幂等成功。
630	     */
631	    @Transactional
632	    public SettleResponse settle(String orderNo) {
633	        CurtailOrder order = dispatchRepository.findOrderByNo(orderNo);
634	        if (order == null) {
635	            throw new ApiNotFoundException("指令不存在：" + orderNo);
636	        }
637	        if (order.getStatus() == OrderStatus.SETTLED) {
638	            return new SettleResponse(order.getId(), order.getOrderNo(),
639	                    order.getStatus().name(), order.getSettledAt(), true);
640	        }
641	        if (order.getStatus() == OrderStatus.SUPERSEDED) {
642	            throw new ApiBadRequestException("指令已被新指令作废，不能日结封存：" + orderNo);
643	        }
644	        Instant now = clock.now();
645	        dispatchRepository.markSettled(order.getId(), now);
646	        return new SettleResponse(order.getId(), order.getOrderNo(),
647	                OrderStatus.SETTLED.name(), now, false);
648	    }
649	
650	    /**
651	     * 指令详情：各轮分摊明细、按机组＋时刻归位的执行曲线、告警链与迟到事件，均可复算。
652	     */
653	    public OrderDetailResponse detail(String orderNo) {
654	        CurtailOrder order = dispatchRepository.findOrderByNo(orderNo);
655	        if (order == null) {
656	            throw new ApiNotFoundException("指令不存在：" + orderNo);
657	        }
658	        List<Turbine> turbines = turbineRepository.findByFarm(order.getFarmCode());
659	        Map<Long, Turbine> turbineById = turbines.stream()
660	                .collect(Collectors.toMap(Turbine::getId, t -> t));
661	
662	        List<DispatchCycle> cycles = dispatchRepository.findCycles(order.getId());
663	        List<Allocation> allAllocations = dispatchRepository.findAllAllocations(order.getId());
664	        List<OrderDetailResponse.CycleView> cycleViews = new ArrayList<>();
665	        for (DispatchCycle c : cycles) {
666	            List<AllocationItem> items = allAllocations.stream()
667	                    .filter(a -> a.getCycleNo() == c.getCycleNo())
668	                    .map(a -> toItem(a, turbineById.get(a.getTurbineId())))
669	                    .toList();
670	            cycleViews.add(new OrderDetailResponse.CycleView(
671	                    c.getCycleNo(), c.getDispatchedAt(), c.getDueAt(), items));
672	        }
673	
674	        List<ExecutionReport> reports =
675	                dispatchRepository.findReportsOfFarm(order.getFarmCode()).stream()
676	                        .filter(r -> r.getOrderId() == order.getId())
677	                        .toList();
678	        List<OrderDetailResponse.ReportPoint> curve = reports.stream()
679	                .map(r -> new OrderDetailResponse.ReportPoint(
680	                        turbineById.get(r.getTurbineId()).getTurbineCode(),
681	                        r.getMeasuredAt(), r.getPowerKw(), r.getReceivedAt()))
682	                .toList();
683	
684	        List<AlertView> alerts = dispatchRepository.findAlerts(order.getId())
685	                .stream()
686	                .map(a -> new AlertView(a.getCycleNo(), a.getType().name(),
687	                        a.getFiredAt(), a.getFarmActualKw(), a.getReallocatedCycleNo()))
688	                .toList();
689	
690	        List<OrderDetailResponse.LateReportView> late = dispatchRepository.findLateReports(order.getId())
691	                .stream()
692	                .map(e -> new OrderDetailResponse.LateReportView(e.getTurbineCode(),
693	                        e.getMeasuredAt(), e.getPowerKw(), e.getRequestId(), e.getRecordedAt()))
694	                .toList();
695	
696	        return new OrderDetailResponse(order.getId(), order.getOrderNo(), order.getFarmCode(),
697	                order.getRequestId(), order.getTargetPowerKw(), order.getStatus().name(),
698	                order.getCurrentCycleNo(), order.getReceivedAt(), order.getSettledAt(),
699	                cycleViews, curve, alerts, late);
700	    }
701	
702	    private OrderReceiveResponse buildReceiveResponse(CurtailOrder order, List<Turbine> turbines,
703	                                                      List<Allocation> allocations,
704	                                                      int farmAvailable, boolean replayed) {
705	        Map<Long, Turbine> byId = new LinkedHashMap<>();
706	        turbines.forEach(t -> byId.put(t.getId(), t));
707	        List<AllocationItem> items = allocations.stream()
708	                .map(a -> toItem(a, byId.get(a.getTurbineId())))
709	                .toList();
710	        boolean noCurtailment = farmAvailable == order.getTargetPowerKw();
711	        return new OrderReceiveResponse(order.getId(), order.getOrderNo(), order.getRequestId(),
712	                order.getFarmCode(), order.getTargetPowerKw(), farmAvailable,
713	                farmAvailable - order.getTargetPowerKw(), order.getStatus().name(),
714	                order.getCurrentCycleNo(), noCurtailment, items, replayed);
715	    }
716	
717	    private AllocationItem toItem(Allocation a, Turbine t) {
718	        return new AllocationItem(
719	                t == null ? String.valueOf(a.getTurbineId()) : t.getTurbineCode(),
720	                a.getBaseAvailableKw(),
721	                t == null ? 0 : t.getTechnicalMinKw(),
722	                a.getTargetPowerKw(),
723	                a.getCurtailKw(),
724	                a.getPlannedPowerKw(),
725	                a.getRealtimeAvailableKw());
726	    }
727	
728	    private DispatchCycle buildCycle(long orderId, int cycleNo, Instant dispatchedAt) {
729	        DispatchCycle cycle = new DispatchCycle();
730	        cycle.setOrderId(orderId);
731	        cycle.setCycleNo(cycleNo);
732	        cycle.setDispatchedAt(dispatchedAt);
733	        cycle.setDueAt(dispatchedAt.plus(DUE_MINUTES, ChronoUnit.MINUTES));
734	        return cycle;
735	    }
736	
737	    private IdempotentRecord newIdempotent(String requestId, String bizType,
738	                                           String fingerprint, Instant now) {
739	        IdempotentRecord record = new IdempotentRecord();
740	        record.setRequestId(requestId);
741	        record.setBizType(bizType);
742	        record.setFingerprint(fingerprint);
743	        record.setCreatedAt(now);
744	        record.setResponseBody("");
745	        return record;
746	    }
747	
748	    private String generateOrderNo(Instant now) {
749	        return "CO" + now.atZone(clock.zone())
750	                .format(java.time.format.DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))
751	                + String.format("%04d", ThreadLocalRandom.current().nextInt(10000));
752	    }
753	
754	    private String toJson(Object value) {
755	        try {
756	            return objectMapper.writeValueAsString(value);
757	        } catch (JsonProcessingException ex) {
758	            throw new IllegalStateException("响应序列化失败", ex);
759	        }
760	    }
761	
762	    private <T> T fromJson(String json, Class<T> type) {
763	        try {
764	            return objectMapper.readValue(json, type);
765	        } catch (JsonProcessingException ex) {
766	            throw new IllegalStateException("首次响应无法还原", ex);
767	        }
768	    }
769	}
