166	    /** 当前版本详情；无任何版本时 404。 */
167	    @Transactional(readOnly = true)
168	    public PlanVersionResponse getCurrentVersion(String farmCode, LocalDate planDate) {
169	        PlanVersion current = planRepository.findCurrentVersion(farmCode, planDate);
170	        if (current == null) {
171	            throw new ApiNotFoundException(
172	                    "风场 " + farmCode + " 在 " + planDate + " 无已发布日前计划");
173	        }
174	        return toVersionResponse(current);
175	    }
176	
177	    /** 指定版本号详情；版本不存在 404（过期版本仍可查询，仅不可被新指令绑定）。 */
178	    @Transactional(readOnly = true)
179	    public PlanVersionResponse getVersion(String farmCode, LocalDate planDate, int versionNo) {
180	        PlanVersion version = planRepository.findVersion(farmCode, planDate, versionNo);
181	        if (version == null) {
182	            throw new ApiNotFoundException(
183	                    "计划版本不存在：" + farmCode + " " + planDate + " v" + versionNo);
184	        }
185	        return toVersionResponse(version);
186	    }
187	
188	    /** 同场同日全部版本（含历史），按版本号升序。 */
189	    @Transactional(readOnly = true)
190	    public List<PlanVersionSummary> listVersions(String farmCode, LocalDate planDate) {
191	        return planRepository.findVersions(farmCode, planDate).stream()
192	                .map(v -> new PlanVersionSummary(v.getId(), v.getFarmCode(), v.getPlanDate(),
193	                        v.getVersionNo(), "Y".equals(v.getCurrentFlag()), v.getPublishedAt()))
194	                .toList();
195	    }
196	
197	    /**
198	     * 整版校验：恰好 96 个不缺段的时段；每段恰好覆盖全场机组各一条（重复机组/多段/少段拒绝）；
199	     * 出力非负且不超过各机组合成装机。任何不满足均整版拒绝。
200	     */
201	    private Map<Integer, Map<String, Integer>> validateWholePlan(
202	            PlanPublishRequest request, List<Turbine> turbines) {
203	        Map<String, Turbine> byCode = turbines.stream()
204	                .collect(Collectors.toMap(Turbine::getTurbineCode, t -> t));
205	        Set<String> farmCodes = turbines.stream()
206	                .map(Turbine::getTurbineCode).collect(Collectors.toSet());
207	
208	        Map<Integer, Map<String, Integer>> bySegment = new HashMap<>();
209	        Set<Integer> indices = new HashSet<>();
210	        for (PlanSegmentInput seg : request.segments()) {
211	            if (seg.segmentIndex() < 0 || seg.segmentIndex() >= SEGMENTS_PER_DAY) {
212	                throw new ApiUnprocessableException(
213	                        "时段序号超出 0..95：" + seg.segmentIndex());
214	            }
215	            Turbine turbine = byCode.get(seg.turbineCode());
216	            if (turbine == null) {
217	                throw new ApiUnprocessableException(
218	                        "计划包含风场 " + request.farmCode() + " 中不存在的机组：" + seg.turbineCode());
219	            }
220	            if (seg.powerKw() > turbine.getRatedPowerKw()) {
221	                throw new ApiUnprocessableException(
222	                        "机组 " + seg.turbineCode() + " 第 " + seg.segmentIndex()
223	                                + " 段核定出力 " + seg.powerKw() + " kW 超过合成装机容量 "
224	                                + turbine.getRatedPowerKw() + " kW，整版拒绝");
225	            }
226	            Map<String, Integer> oneSegment =
227	                    bySegment.computeIfAbsent(seg.segmentIndex(), k -> new HashMap<>());
228	            if (oneSegment.put(seg.turbineCode(), seg.powerKw()) != null) {
229	                throw new ApiUnprocessableException(
230	                        "机组 " + seg.turbineCode() + " 在第 " + seg.segmentIndex()
231	                                + " 段重复出现，整版拒绝");
232	            }
233	            indices.add(seg.segmentIndex());
234	        }
235	
236	        if (indices.size() != SEGMENTS_PER_DAY) {
237	            throw new ApiUnprocessableException(
238	                    "计划缺段：仅含 " + indices.size() + " 个时段，须完整覆盖 96 个十五分钟时段，整版拒绝");
239	        }
240	        for (int idx = 0; idx < SEGMENTS_PER_DAY; idx++) {
241	            Map<String, Integer> oneSegment = bySegment.get(idx);
242	            if (oneSegment == null || !oneSegment.keySet().equals(farmCodes)) {
243	                throw new ApiUnprocessableException(
244	                        "第 " + idx + " 段机组集合不完整（须恰好覆盖全场每台机组各一条），整版拒绝");
245	            }
246	        }
247	        return bySegment;
248	    }
249	
250	    private PlanPublishResponse resolvePublishIdempotent(IdempotentRecord existing, String fingerprint) {
251	        if (!existing.getFingerprint().equals(fingerprint)) {
252	            throw new ApiConflictException("相同 requestId 的业务参数与首次请求不一致");
253	        }
254	        if (existing.getResponseBody() != null && !existing.getResponseBody().isBlank()) {
255	            return fromJson(existing.getResponseBody(), PlanPublishResponse.class).asReplay();
256	        }
257	        throw new ApiConflictException("首次请求仍在处理中");
258	    }
259	
260	    private PlanVersionResponse toVersionResponse(PlanVersion version) {
261	        Map<Long, String> codeById = turbineRepository.findByFarm(version.getFarmCode()).stream()
262	                .collect(Collectors.toMap(Turbine::getId, Turbine::getTurbineCode));
263	        List<PlanVersionResponse.SegmentView> views = planRepository.findSegments(version.getId())
264	                .stream()
265	                .sorted(Comparator.comparingInt(PlanSegment::getSegmentIndex)
266	                        .thenComparing(s -> codeById.getOrDefault(s.getTurbineId(),
267	                                String.valueOf(s.getTurbineId()))))
268	                .map(s -> {
269	                    Instant start = version.getPlanDate().atStartOfDay()
270	                            .plusMinutes(15L * s.getSegmentIndex()).toInstant(ZoneOffset.UTC);
271	                    return new PlanVersionResponse.SegmentView(s.getSegmentIndex(), start,
272	                            start.plusSeconds(15 * 60L),
273	                            codeById.getOrDefault(s.getTurbineId(), String.valueOf(s.getTurbineId())),
274	                            s.getPowerKw());
275	                })
276	                .toList();
277	        return new PlanVersionResponse(version.getId(), version.getFarmCode(), version.getPlanDate(),
278	                version.getVersionNo(), "Y".equals(version.getCurrentFlag()),
279	                version.getPublishedAt(), version.getRequestId(), views);
280	    }
281	
282	    /**
283	     * 结构化指纹：TLV 规范编码，精确到发布时刻；段集合按（时段、机组）确定性排序。
284	     * 合法文本含分隔符也无歧义：边界由长度前缀决定。
285	     */
286	    private String fingerprint(PlanPublishRequest request, Instant publishedAt) {
287	        List<String> segmentTokens = request.segments().stream()
288	                .sorted(Comparator.comparingInt(PlanSegmentInput::segmentIndex)
289	                        .thenComparing(PlanSegmentInput::turbineCode))
290	                .map(s -> Canonical.obj(
291	                        "segmentIndex", Canonical.integer(s.segmentIndex()),
292	                        "turbineCode", Canonical.str(s.turbineCode()),
293	                        "powerKw", Canonical.integer(s.powerKw())))
294	                .toList();
295	        String canonical = Canonical.obj(
296	                "bizType", Canonical.str("PLAN_PUBLISH"),
297	                "requestId", Canonical.str(request.requestId()),
298	                "farmCode", Canonical.str(request.farmCode()),
299	                "planDate", Canonical.date(request.planDate()),
300	                "expectedVersion", Canonical.integer(request.expectedVersion()),
301	                "operateAt", Canonical.instant(publishedAt),
302	                "segments", Canonical.list(segmentTokens));
303	        return Canonical.sha256(canonical);
304	    }
305	
306	    private String toJson(Object value) {
307	        try {
308	            return objectMapper.writeValueAsString(value);
309	        } catch (JsonProcessingException ex) {
310	            throw new IllegalStateException("响应序列化失败", ex);
311	        }
312	    }
313	
314	    private <T> T fromJson(String json, Class<T> type) {
315	        try {
316	            return objectMapper.readValue(json, type);
317	        } catch (JsonProcessingException ex) {
318	            throw new IllegalStateException("首次响应无法还原", ex);
319	        }
320	    }
321	}
