package com.example.starter.domain;

import java.time.Instant;

/**
 * 风电机组。
 * ratedPowerKw 装机容量（kW）；technicalMinKw 技术出力下限（kW，额定的 15%）；
 * availablePowerKw 最新可用出力（kW），随执行回报刷新。
 */
public class Turbine {

    private Long id;
    private String farmCode;
    private String turbineCode;
    private int ratedPowerKw;
    private int technicalMinKw;
    private int availablePowerKw;
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getFarmCode() {
        return farmCode;
    }

    public void setFarmCode(String farmCode) {
        this.farmCode = farmCode;
    }

    public String getTurbineCode() {
        return turbineCode;
    }

    public void setTurbineCode(String turbineCode) {
        this.turbineCode = turbineCode;
    }

    public int getRatedPowerKw() {
        return ratedPowerKw;
    }

    public void setRatedPowerKw(int ratedPowerKw) {
        this.ratedPowerKw = ratedPowerKw;
    }

    public int getTechnicalMinKw() {
        return technicalMinKw;
    }

    public void setTechnicalMinKw(int technicalMinKw) {
        this.technicalMinKw = technicalMinKw;
    }

    public int getAvailablePowerKw() {
        return availablePowerKw;
    }

    public void setAvailablePowerKw(int availablePowerKw) {
        this.availablePowerKw = availablePowerKw;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.dto;

import java.time.LocalDate;
import java.util.List;

/**
 * 计划绑定模式限电指令受理/重放响应。
 * 与旧模式响应并列：额外回传冻结的版本号、UTC 日期与时段序号。
 * replayed=true 表示同键同参重放，内容与首次冻结结果一致。
 */
public record PlanOrderReceiveResponse(
        Long orderId,
        String orderNo,
        String requestId,
        String farmCode,
        int targetPowerKw,
        int farmParticipatingKw,
        int curtailedKw,
        String status,
        int cycleNo,
        boolean noCurtailment,
        Long planVersionId,
        int planVersionNo,
        LocalDate planDate,
        int segmentIndex,
        boolean versionCurrent,
        List<AllocationItem> allocations,
        boolean replayed) {

    public PlanOrderReceiveResponse asReplay() {
        return new PlanOrderReceiveResponse(orderId, orderNo, requestId, farmCode, targetPowerKw,
                farmParticipatingKw, curtailedKw, status, cycleNo, noCurtailment,
                planVersionId, planVersionNo, planDate, segmentIndex, versionCurrent,
                allocations, true);
    }
}

