40	    @Test
41	    @DisplayName("同一 requestId 并发接收：唯一受理，其余全部返回首次结果")
42	    void sameRequestIdConcurrentAcceptedOnce() throws Exception {
43	        int threads = 8;
44	        ExecutorService pool = Executors.newFixedThreadPool(threads);
45	        CountDownLatch start = new CountDownLatch(1);
46	        List<Future<OrderReceiveResponse>> futures = new ArrayList<>();
47	
48	        for (int i = 0; i < threads; i++) {
49	            futures.add(pool.submit(() -> {
50	                start.await();
51	                return dispatchService.receive(new OrderReceiveRequest("same-key", FARM, 5000));
52	            }));
53	        }
54	        start.countDown();
55	
56	        List<OrderReceiveResponse> results = new ArrayList<>();
57	        for (Future<OrderReceiveResponse> f : futures) {
58	            results.add(f.get(30, TimeUnit.SECONDS));
59	        }
60	        pool.shutdown();
61	
62	        long distinctOrderIds = results.stream().map(OrderReceiveResponse::orderId).distinct().count();
63	        assertThat(distinctOrderIds).isEqualTo(1);
64	        long firstCount = results.stream().filter(r -> !r.replayed()).count();
65	        long replayCount = results.stream().filter(OrderReceiveResponse::replayed).count();
66	        assertThat(firstCount).isEqualTo(1);
67	        assertThat(replayCount).isEqualTo(threads - 1);
68	
69	        Integer orderCount = jdbc.queryForObject(
70	                "SELECT COUNT(*) FROM curtail_order", Integer.class);
71	        Integer idemCount = jdbc.queryForObject(
72	                "SELECT COUNT(*) FROM idempotent_record WHERE request_id = 'same-key'", Integer.class);
73	        Integer activeCount = jdbc.queryForObject(
74	                "SELECT COUNT(*) FROM curtail_order WHERE active_flag = 'Y'", Integer.class);
75	        assertThat(orderCount).isEqualTo(1);
76	        assertThat(idemCount).isEqualTo(1);
77	        assertThat(activeCount).isEqualTo(1);
78	    }
