82	    void sameFarmSameTimeConcurrentOnlyOneAccepted() throws Exception {
83	        int threads = 8;
84	        ExecutorService pool = Executors.newFixedThreadPool(threads);
85	        CountDownLatch start = new CountDownLatch(1);
86	        List<Future<?>> futures = new ArrayList<>();
87	
88	        for (int i = 0; i < threads; i++) {
89	            final int idx = i;
90	            futures.add(pool.submit(() -> {
91	                start.await();
92	                return dispatchService.receive(
93	                        new OrderReceiveRequest("key-" + idx, FARM, 5000));
94	            }));
95	        }
96	        start.countDown();
97	
98	        int success = 0;
99	        int conflict = 0;
100	        for (Future<?> f : futures) {
101	            try {
102	                f.get(30, TimeUnit.SECONDS);
103	                success++;
104	            } catch (Exception ex) {
105	                // java.util.concurrent.ExecutionException 包装 ApiConflictException
106	                boolean isConflict = ex.getCause() instanceof ApiConflictException
107	                        || (ex.getCause() != null
108	                            && ex.getCause().getCause() instanceof ApiConflictException);
109	                assertThat(isConflict).isTrue();
110	                conflict++;
111	            }
112	        }
113	        pool.shutdown();
114	
115	        assertThat(success).isEqualTo(1);
116	        assertThat(conflict).isEqualTo(threads - 1);
117	
118	        Integer activeCount = jdbc.queryForObject(
119	                "SELECT COUNT(*) FROM curtail_order WHERE active_flag = 'Y'", Integer.class);
120	        Integer orderCount = jdbc.queryForObject(
121	                "SELECT COUNT(*) FROM curtail_order", Integer.class);
122	        assertThat(activeCount).isEqualTo(1);
123	        assertThat(orderCount).isEqualTo(1);
124	    }
