150	                .isEqualTo(second.orderId());
151	        assertThat((String) newOrder.get("STATUS")).isEqualTo(OrderStatus.DISPATCHED.name());
152	        assertThat((String) newOrder.get("ACTIVE_FLAG")).isEqualTo("Y");
