package com.example.starter.domain;

/**
 * 受控分段计划生命周期状态。
 * EXECUTING 执行中（占用机组）；PAUSED 机组可用状态失效暂停（已执行历史不回退，可取消释放占用）；
 * COMPLETED 最后一分钟确认完成（释放占用）；CANCELED 暂停后取消或指令作废/封存（释放占用，不恢复原功率）。
 */
public enum StagedPlanStatus {
    EXECUTING,
    PAUSED,
    COMPLETED,
    CANCELED
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 受控分段计划：限电指令的可选分段执行模式。
 * planVersion 从 1 起，调用方修改带 expectedVersion、成功加 1，超时重分配亦加 1；
 * startAt 为当前版本启动 UTC 时刻，回执分钟时刻 = startAt + 序号分钟；
 * currentMinute 为当前版本已确认分钟序号（0 表示尚未确认）。
 */
public class StagedPlan {

    private Long id;
    private Long orderId;
    private int planVersion;
    private StagedPlanStatus status;
    private Instant startAt;
    private int currentMinute;
    private int durationMinutes;
    private Instant createdAt;
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getOrderId() {
        return orderId;
    }

    public void setOrderId(Long orderId) {
        this.orderId = orderId;
    }

    public int getPlanVersion() {
        return planVersion;
    }

    public void setPlanVersion(int planVersion) {
        this.planVersion = planVersion;
    }

    public StagedPlanStatus getStatus() {
        return status;
    }

    public void setStatus(StagedPlanStatus status) {
        this.status = status;
    }

    public Instant getStartAt() {
        return startAt;
    }

    public void setStartAt(Instant startAt) {
        this.startAt = startAt;
    }

    public int getCurrentMinute() {
        return currentMinute;
    }

    public void setCurrentMinute(int currentMinute) {
        this.currentMinute = currentMinute;
    }

    public int getDurationMinutes() {
        return durationMinutes;
    }

    public void setDurationMinutes(int durationMinutes) {
        this.durationMinutes = durationMinutes;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.domain;

/**
 * 分段计划参与机组：冻结当前版本起始功率、最终分摊目标与每分钟升降上限。
 * occupiedFlag='Y' 表示机组被本计划占用（每机组同一时刻至多一份执行中分段计划），
 * 完成/取消/指令作废时置 NULL 释放。
 */
public class StagedPlanTurbine {

    private Long id;
    private Long planId;
    private Long turbineId;
    private int startPowerKw;
    private int targetPowerKw;
    private int rampKwPerMin;
    private int deadlineMinutes;
    private String occupiedFlag;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getPlanId() {
        return planId;
    }

    public void setPlanId(Long planId) {
        this.planId = planId;
    }

    public Long getTurbineId() {
        return turbineId;
    }

    public void setTurbineId(Long turbineId) {
        this.turbineId = turbineId;
    }

    public int getStartPowerKw() {
        return startPowerKw;
    }

    public void setStartPowerKw(int startPowerKw) {
        this.startPowerKw = startPowerKw;
    }

    public int getTargetPowerKw() {
        return targetPowerKw;
    }

    public void setTargetPowerKw(int targetPowerKw) {
        this.targetPowerKw = targetPowerKw;
    }

    public int getRampKwPerMin() {
        return rampKwPerMin;
    }

    public void setRampKwPerMin(int rampKwPerMin) {
        this.rampKwPerMin = rampKwPerMin;
    }

    public int getDeadlineMinutes() {
        return deadlineMinutes;
    }

    public void setDeadlineMinutes(int deadlineMinutes) {
        this.deadlineMinutes = deadlineMinutes;
    }

    public String getOccupiedFlag() {
