package com.example.starter.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 受控分段指令的参与机组登记项。
 *
 * @param turbineCode     机组编码（须属于该风场，不可重复）
 * @param startPowerKw    起始整数 kW 实际功率，须在原最低保留与当时可用出力之间
 * @param rampKwPerMin    每分钟正整数升降上限（kW）
 * @param deadlineMinutes 期限分钟数 1..15；期限内须能按上限到达冻结目标，否则全单拒绝
 */
public record StagedTurbineInput(
        @NotBlank String turbineCode,
        @PositiveOrZero int startPowerKw,
        @Positive int rampKwPerMin,
        @Min(1) @Max(15) int deadlineMinutes) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

/**
 * 受控分段执行模式限电指令登记请求（可选模式；旧未启用指令保持原行为）。
 * 最终目标仍由原最低保留、日前基数（可选绑定）与分摊规则决定；
 * 登记冻结原计划基数、最终分配与各机组斜率，生成完整阶梯。
 *
 * @param requestId     幂等键，覆盖全部业务字段与精确时刻
 * @param farmCode      风场编码
 * @param targetPowerKw 限电后全场目标出力（kW，正整数）
 * @param operateAt     调用方给出的精确受理时刻（UTC，ISO-8601），参与结构化指纹
 * @param planDate      可选：绑定日前计划的 UTC 日期；三者（planDate/segmentIndex/planVersionNo）同空或同非空
 * @param segmentIndex  可选：绑定时段序号 0..95
 * @param planVersionNo 可选：绑定的当前计划版本号
 * @param turbines      参与机组登记项（非空；未列入的机组不占用、走旧回执入口）
 */
public record StagedOrderReceiveRequest(
        @NotBlank String requestId,
        @NotBlank String farmCode,
        @Positive int targetPowerKw,
        @NotNull Instant operateAt,
        LocalDate planDate,
        @Min(0) @Max(95) Integer segmentIndex,
        @Positive Integer planVersionNo,
        @NotEmpty List<StagedTurbineInput> turbines) {

    /** 是否绑定日前计划基数（三字段同非空）。 */
    public boolean planBound() {
        return planDate != null && segmentIndex != null && planVersionNo != null;
    }

    /** 绑定三字段是否部分缺失（非法）。 */
    public boolean planBindingPartial() {
        return !planBound()
                && (planDate != null || segmentIndex != null || planVersionNo != null);
    }
}

package com.example.starter.dto;

/**
 * 分段计划参与机组视图：冻结的起始功率、最终目标、斜率与期限，以及按斜率到达目标所需分钟数。
 */
public record StagedTurbineView(
        String turbineCode,
        int startPowerKw,
        int targetPowerKw,
        int rampKwPerMin,
        int deadlineMinutes,
        int neededMinutes) {
}

package com.example.starter.dto;

import java.time.Instant;
import java.util.List;

/**
 * 受控分段指令登记/重放响应。
 * 回传冻结的分段计划（版本 1、启动 UTC 时刻、期限）与各机组斜率；
 * replayed=true 表示同键同参重放，内容与首次冻结结果一致。
 */
public record StagedOrderReceiveResponse(
        Long orderId,
        String orderNo,
        String requestId,
        String farmCode,
        int targetPowerKw,
        int farmAvailableKw,
        int curtailedKw,
        String status,
        Long planId,
        int planVersion,
        String planStatus,
        Instant startAt,
        int durationMinutes,
        List<StagedTurbineView> turbines,
        List<AllocationItem> allocations,
        boolean replayed) {

    public StagedOrderReceiveResponse asReplay() {
        return new StagedOrderReceiveResponse(orderId, orderNo, requestId, farmCode, targetPowerKw,
                farmAvailableKw, curtailedKw, status, planId, planVersion, planStatus, startAt,
                durationMinutes, turbines, allocations, true);
    }
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 分段回执单机功率项：功率须等于冻结的该分钟阶梯值。
 */
public record StagedReceiptItem(
        @NotBlank String turbineCode,
        @PositiveOrZero int powerKw) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Positive;

import java.util.List;

/**
 * 受控分段计划分钟回执请求。
 * 整分钟一起确认：items 须恰好覆盖全部参与机组且功率等于冻结阶梯；
 * 缺一机组零更新；分钟序号不可提前、不可跳号。
 *
 * @param requestId 幂等键，覆盖全部业务字段
 * @param orderNo   指令单号（其分段计划为回执目标）
 * @param minuteNo  分钟序号（从 1 起，须等于当前进度+1）
 * @param items     全部参与机组该分钟功率
 */
public record StagedReceiptRequest(
        @NotBlank String requestId,
        @NotBlank String orderNo,
        @Positive int minuteNo,
        @NotEmpty List<StagedReceiptItem> items) {
}

package com.example.starter.dto;

import java.time.Instant;
import java.util.List;

/**
 * 分钟回执响应。
 * executed=false 且 paused=true 表示每分钟重查机组可用状态时发现失效机组：
 * 该分钟未执行（零更新）、计划已暂停，已执行历史不回退。
 * completed=true 表示最后一分钟确认完成，指令完成。
 */
public record StagedReceiptResponse(
        String requestId,
        String orderNo,
        Long planId,
        int planVersion,
        int minuteNo,
        Instant minuteAt,
        boolean executed,
        boolean paused,
        boolean completed,
        int currentMinute,
        List<StagedReceiptItem> applied,
        boolean replayed) {

    public StagedReceiptResponse asReplay() {
        return new StagedReceiptResponse(requestId, orderNo, planId, planVersion, minuteNo,
                minuteAt, executed, paused, completed, currentMinute, applied, true);
    }
}

package com.example.starter.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 分段计划修改的机组斜率项：新的每分钟升降上限与期限；最终目标不变（仍由冻结分配决定）。
 */
public record StagedSlopeInput(
        @NotBlank String turbineCode,
        @Positive int rampKwPerMin,
        @Min(1) @Max(15) int deadlineMinutes) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Positive;

import java.util.List;

/**
 * 分段计划修改请求：带 expectedVersion 乐观并发控制。
 * 从当前实际功率按新斜率重排剩余阶梯（目标不变），成功版本加 1，旧版 409；
 * 须恰好覆盖全部参与机组。
 *
 * @param requestId       幂等键，覆盖全部业务字段
 * @param expectedVersion 调用方持有的当前计划版本号
 * @param turbines        全部参与机组的新斜率与期限
 */
public record StagedPlanModifyRequest(
        @NotBlank String requestId,
        @Positive int expectedVersion,
        @NotEmpty List<StagedSlopeInput> turbines) {
}

package com.example.starter.dto;

import java.time.Instant;
import java.util.List;

/**
 * 分段计划修改/重放响应：重排后的版本号、启动时刻与机组斜率。
 */
public record StagedPlanModifyResponse(
        String requestId,
        String orderNo,
        Long planId,
        int planVersion,
        String planStatus,
        Instant startAt,
        int durationMinutes,
        List<StagedTurbineView> turbines,
        boolean replayed) {

    public StagedPlanModifyResponse asReplay() {
        return new StagedPlanModifyResponse(requestId, orderNo, planId, planVersion, planStatus,
                startAt, durationMinutes, turbines, true);
    }
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 分段计划取消请求：仅暂停中的计划可取消；取消释放机组占用，不自动恢复原功率。
 *
 * @param requestId 幂等键，覆盖全部业务字段
 */
public record StagedPlanCancelRequest(
        @NotBlank String requestId) {
}

package com.example.starter.dto;

/**
 * 分段计划取消/重放响应：status 为 CANCELED，机组占用已释放，实际功率保持最后确认值。
 */
public record StagedPlanCancelResponse(
        String requestId,
        String orderNo,
        Long planId,
        int planVersion,
        String planStatus,
        boolean replayed) {

    public StagedPlanCancelResponse asReplay() {
        return new StagedPlanCancelResponse(requestId, orderNo, planId, planVersion, planStatus, true);
    }
}

package com.example.starter.dto;

import java.time.Instant;
import java.util.List;

/**
 * 分段计划详情：当前版本状态/进度/期限、机组斜率与逐分钟冻结阶梯（含确认情况），可复算。
 */
public record StagedPlanDetailResponse(
        String orderNo,
        Long planId,
        int planVersion,
        String planStatus,
        Instant startAt,
        int currentMinute,
        int durationMinutes,
        List<StagedTurbineView> turbines,
        List<MinuteView> minutes) {

    /**
     * 单分钟视图：minuteAt=启动时刻+序号分钟；confirmed 表示该分钟已整分钟确认。
     */
    public record MinuteView(
            int minuteNo,
            Instant minuteAt,
            boolean confirmed,
            Instant confirmedAt,
            List<StagedReceiptItem> items) {
    }
}

