private String fingerprintStagedOrder(StagedOrderReceiveRequest request) {
    List<String> turbineTokens = request.turbines().stream()
            .sorted(Comparator.comparing(StagedTurbineInput::turbineCode))
            .map(t -> Canonical.obj(
